using System;using System.IO;using System.Collections.Generic;using Ashfall.Core;using Ashfall.Modules.Player;using Ashfall.Integration.PersonalSettings;
sealed class R6Authority:IAuthorityGate {public RuleResult Validate(CommandContext c){return c.IsAuthority?RuleResult.Accept():RuleResult.Reject("authority");}}
static class CurrentPlayerR6Test {
 static void Check(bool b){if(!b)throw new Exception("PlayerR6 publication");}static CommandContext C(string id,bool host){return new CommandContext("s","p",id,1,0,host);}static float Speed(Locomotion m,long t){return m.Step(new InputFrame{Tracked=true,Tick=t,Sequence=t,MoveY=1},new MotionEnvironment{Grounded=true},.02f).Velocity.Z;}
 public static int Main(string[] args){try{Directory.CreateDirectory(args[0]);var h=new PersonalSettingsAdapter(Path.Combine(args[0],"current.ashfall-settings.json"),SettingsSource.Quest,new R5Actions());h.CaptureSettings();var input=new PlayerInput();var tuning=h.Effective.CreatePlayerTuning();var pub=new PlayerSettingsPublication(input,tuning,new R6Authority(),"s","p",0);var motor=new Locomotion(tuning);var old=new TypedPlayerSettingsPort(h.Effective);Check(pub.Publish(C("normal",true),0,tuning,old,DominantHand.Right,SprintBinding.LeftClick).Accepted);motor.Settings=pub.Effective;Check(Math.Abs(Speed(motor,1)-PlayerTuning.WalkSpeed)<.0002);Check(h.CommitSettings(new Dictionary<string,string>{{"comfort_speed","true"},{"dominant_hand","left"}}).Accepted);var next=new TypedPlayerSettingsPort(h.Effective);Check(!pub.Publish(C("forged",false),1,h.Effective.CreatePlayerTuning(),next,DominantHand.Left,SprintBinding.LeftGrip).Accepted);Check(Object.ReferenceEquals(pub.Effective,old));Check(Math.Abs(Speed(motor,2)-PlayerTuning.WalkSpeed)<.0002);Check(pub.Publish(C("comfort",true),1,h.Effective.CreatePlayerTuning(),next,DominantHand.Left,SprintBinding.LeftGrip).Accepted);motor.Settings=pub.Effective;Check(Math.Abs(Speed(motor,3)-2.6f)<.0002);Check(input.Ownership.Dominant==DominantHand.Left&&input.Ownership.Sprint==SprintBinding.LeftGrip);Check(!pub.Publish(C("stale",true),1,tuning,old,DominantHand.Right,SprintBinding.LeftClick).Accepted);Check(Math.Abs(Speed(motor,4)-2.6f)<.0002);Console.WriteLine("PASS current pinned PlayerR6 authorized publication same real motor comfort identity ownership rejected authority and stale revision");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
